/**
 * @suppress
 */
public object FfiConverterTypeMemoryStore: FfiConverter<MemoryStore, Pointer> {
    internal val handleMap = UniffiHandleMap<MemoryStore>()

    override fun lower(value: MemoryStore): Pointer {
        return Pointer(handleMap.insert(value))
    }

    override fun lift(value: Pointer): MemoryStore {
        return MemoryStoreImpl(value)
    }

    override fun read(buf: ByteBuffer): MemoryStore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: MemoryStore) = 8UL

    override fun write(value: MemoryStore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}


