/**
 * 探测错误（flat error：仅 lower to_string() 文本）
 *
 * uniffi 0.29 不支持 `Result<T, String>` 直接导出（Kotlin 生成器只认
 * Enum/Object 错误类型），故定义本枚举承载错误文本，Kotlin 侧抛出
 * `ApiProbeException(message)`。
 */
sealed class ApiProbeException(message: String): kotlin.Exception(message) {
        
        class Message(message: String) : ApiProbeException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<ApiProbeException> {
        override fun lift(error_buf: RustBuffer.ByValue): ApiProbeException = FfiConverterTypeApiProbeError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeApiProbeError : FfiConverterRustBuffer<ApiProbeException> {
    override fun read(buf: ByteBuffer): ApiProbeException {
        
            return when(buf.getInt()) {
            1 -> ApiProbeException.Message(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: ApiProbeException): ULong {
        return 4UL
    }

    override fun write(value: ApiProbeException, buf: ByteBuffer) {
        when(value) {
            is ApiProbeException.Message -> {
                buf.putInt(1)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



